// Byte-sequence primitives.
//
// A "byte sequence" here is a plain JS Array whose members are integers in
// [0, 255].  Plain arrays are used deliberately: this port must model Python's
// immutable `bytes` semantics without leaning on any typed-array machinery.

/** Big-endian integer value of a byte sequence, as a BigInt. */
export function bytesToInt(bytes) {
  let acc = 0n;
  for (const byte of bytes) {
    acc = acc * 256n + BigInt(byte);
  }
  return acc;
}

/**
 * Big-endian byte sequence for a non-negative BigInt, with no leading zero
 * padding.  Zero yields an empty sequence, mirroring Python's
 * `int(0).to_bytes(0, 'big')` / the `while acc > 0` drain loop in base58.
 */
export function intToBytes(value) {
  const out = [];
  let acc = value;
  while (acc > 0n) {
    out.push(Number(acc % 256n));
    acc /= 256n;
  }
  out.reverse();
  return out;
}

/** Python's `bytes.lstrip(single_byte)`: drop leading runs of one byte value. */
export function lstripByte(bytes, byteValue) {
  let start = 0;
  while (start < bytes.length && bytes[start] === byteValue) {
    start += 1;
  }
  return bytes.slice(start);
}

/** Python's `b'\\xNN' * count`. */
export function repeatByte(byteValue, count) {
  const out = [];
  for (let i = 0; i < count; i += 1) {
    out.push(byteValue);
  }
  return out;
}

/** Python's `bytes + bytes`. */
export function concatBytes(left, right) {
  return left.concat(right);
}

/** Byte sequence of an ASCII-only literal, e.g. the base58 alphabet. */
export function asciiLiteralToBytes(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) {
    out.push(text.charCodeAt(i));
  }
  return out;
}

