// Python `str` semantics that the script depends on: the whitespace class used
// by `str.rstrip()`, printability for `repr()`, and the escape spelling the
// codec machinery uses inside UnicodeEncodeError messages.

// Code points for which Python's str.isspace() is true.  Verified against the
// reference build: 0x1c-0x1f and 0x85 count as whitespace, U+200B does not.
const WHITESPACE_CODEPOINTS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d,
  0x1c, 0x1d, 0x1e, 0x1f,
  0x20, 0x85, 0xa0,
  0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f,
  0x3000,
]);

export function isPyWhitespace(codePoint) {
  return WHITESPACE_CODEPOINTS.has(codePoint);
}

/** Split a JS string into an array of code points, as Python indexes a str. */
export function toCodePoints(text) {
  return Array.from(text);
}

/** Python's `str.rstrip()` with no argument. */
export function pyRstrip(text) {
  const chars = toCodePoints(text);
  let end = chars.length;
  while (end > 0 && isPyWhitespace(chars[end - 1].codePointAt(0))) {
    end -= 1;
  }
  return chars.slice(0, end).join('');
}

/** Py_UNICODE_ISPRINTABLE, restricted to the ASCII range we can observe. */
export function isAsciiPrintable(codePoint) {
  return codePoint >= 0x20 && codePoint <= 0x7e;
}

function hex(codePoint, width) {
  return codePoint.toString(16).padStart(width, '0');
}

/**
 * How CPython spells the offending character inside a UnicodeEncodeError
 * message: always an escape, never the literal character.
 */
export function codecCharEscape(codePoint) {
  if (codePoint < 0x100) {
    return `\\x${hex(codePoint, 2)}`;
  }
  if (codePoint < 0x10000) {
    return `\\u${hex(codePoint, 4)}`;
  }
  return `\\U${hex(codePoint, 8)}`;
}

/**
 * `repr()` of a one-character str whose code point is ASCII.  Used for the
 * "Invalid character {!r}" message, where the character always came out of an
 * ASCII-encoded buffer.
 */
export function reprAsciiChar(codePoint) {
  const quote = codePoint === 0x27 /* ' */ ? '"' : "'";
  let body;
  if (codePoint === quote.charCodeAt(0) || codePoint === 0x5c /* \ */) {
    body = `\\${String.fromCharCode(codePoint)}`;
  } else if (codePoint === 0x09) {
    body = '\\t';
  } else if (codePoint === 0x0a) {
    body = '\\n';
  } else if (codePoint === 0x0d) {
    body = '\\r';
  } else if (isAsciiPrintable(codePoint)) {
    body = String.fromCharCode(codePoint);
  } else {
    body = `\\x${hex(codePoint, 2)}`;
  }
  return `${quote}${body}${quote}`;
}

