// Python-shaped exceptions plus the traceback rendering the CPython runtime
// emits on an unhandled error.

/**
 * An exception that carries the Python-side frame stack it would have
 * propagated through, so `renderTraceback` can reproduce the interpreter's
 * stderr output.
 */
export class PyException extends Error {
  constructor(typeName, detail, frames) {
    super(`${typeName}: ${detail}`);
    this.name = typeName;
    this.typeName = typeName;
    this.detail = detail;
    this.frames = frames ?? [];
  }

  /** Prepend the frames the exception unwound through on its way out. */
  withFrames(frames) {
    this.frames = frames.concat(this.frames);
    return this;
  }
}

export class PyValueError extends PyException {
  constructor(detail, frames) {
    super('ValueError', detail, frames);
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(detail, frames) {
    super('UnicodeEncodeError', detail, frames);
  }
}

/**
 * Build the text of an interpreter traceback.  Each frame is
 * `{ file, line, name, source?, caret? }`; `source` and `caret` are the
 * echoed statement and the `^^^` underline CPython 3.11+ adds for frames it
 * has source for.
 */
export function renderTraceback(exception) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of exception.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.source !== undefined) {
      lines.push(`    ${frame.source}`);
    }
    if (frame.caret !== undefined) {
      lines.push(`    ${frame.caret}`);
    }
  }
  lines.push(`${exception.typeName}: ${exception.detail}`);
  return `${lines.join('\n')}\n`;
}

