// Python's `repr()` for a bytes object, i.e. what `print(b'...')` writes.

import { isAsciiPrintable } from './pyunicode.mjs';

/**
 * CPython picks a double quote only when the payload contains an apostrophe
 * and no double quote; otherwise it uses single quotes and escapes any
 * apostrophe it finds.
 */
function chooseQuote(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  return hasSingle && !hasDouble ? 0x22 : 0x27;
}

export function bytesRepr(bytes) {
  const quote = chooseQuote(bytes);
  let body = '';
  for (const byte of bytes) {
    if (byte === quote || byte === 0x5c /* \ */) {
      body += `\\${String.fromCharCode(byte)}`;
    } else if (byte === 0x09) {
      body += '\\t';
    } else if (byte === 0x0a) {
      body += '\\n';
    } else if (byte === 0x0d) {
      body += '\\r';
    } else if (isAsciiPrintable(byte)) {
      body += String.fromCharCode(byte);
    } else {
      body += `\\x${byte.toString(16).padStart(2, '0')}`;
    }
  }
  const q = String.fromCharCode(quote);
  return `b${q}${body}${q}`;
}

