// Base58 (Bitcoin alphabet), reimplemented from the observable behaviour of the
// `base58` PyPI module.
//
// Frame metadata on the raised errors mirrors the module's own call stack so an
// unhandled failure prints the same traceback as the reference build.

import {
  asciiLiteralToBytes,
  bytesToInt,
  concatBytes,
  intToBytes,
  lstripByte,
  repeatByte,
} from './byteseq.mjs';
import { encodeAsciiStrict } from './codecs.mjs';
import { PyValueError } from './pyerrors.mjs';
import { pyRstrip, reprAsciiChar } from './pyunicode.mjs';

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const MODULE = 'base58/__init__.py';

const ALPHABET_BYTES = asciiLiteralToBytes(BITCOIN_ALPHABET);
const BASE = BigInt(ALPHABET_BYTES.length);

const DECODE_MAP = new Map(ALPHABET_BYTES.map((byte, index) => [byte, index]));

/** `scrub_input`: coerce a str to bytes via the strict ASCII codec. */
function scrubInput(value) {
  if (typeof value === 'string') {
    try {
      return encodeAsciiStrict(value);
    } catch (error) {
      throw error.withFrames([{ file: MODULE, line: 30, name: 'scrub_input' }]);
    }
  }
  return value;
}

/** `b58encode_int` */
export function b58encodeInt(value, { defaultOne = true } = {}) {
  if (value === 0n && defaultOne) {
    return [ALPHABET_BYTES[0]];
  }
  const digits = [];
  let acc = value;
  while (acc > 0n) {
    digits.push(ALPHABET_BYTES[Number(acc % BASE)]);
    acc /= BASE;
  }
  digits.reverse();
  return digits;
}

/** `b58decode_int` */
export function b58decodeInt(value) {
  const bytes = scrubInput(value);
  let acc = 0n;
  for (const byte of bytes) {
    const digit = DECODE_MAP.get(byte);
    if (digit === undefined) {
      throw new PyValueError(`Invalid character ${reprAsciiChar(byte)}`, [
        { file: MODULE, line: 104, name: 'b58decode_int' },
      ]);
    }
    acc = acc * BASE + BigInt(digit);
  }
  return acc;
}

/**
 * `b58encode`: strip leading NUL bytes, encode the remaining big-endian
 * integer, then restore one alphabet-zero character per stripped byte.
 */
export function b58encode(value) {
  const scrubbed = scrubInput(value);
  const origLen = scrubbed.length;
  const stripped = lstripByte(scrubbed, 0x00);
  const newLen = stripped.length;
  const encoded = b58encodeInt(bytesToInt(stripped), { defaultOne: false });
  return concatBytes(repeatByte(ALPHABET_BYTES[0], origLen - newLen), encoded);
}

/**
 * `b58decode`: trailing whitespace is tolerated (leading whitespace is not),
 * and each leading alphabet-zero character becomes one NUL byte.
 */
export function b58decode(value) {
  const trimmed = typeof value === 'string' ? pyRstrip(value) : value;

  let scrubbed;
  try {
    scrubbed = scrubInput(trimmed);
  } catch (error) {
    throw error.withFrames([{ file: MODULE, line: 118, name: 'b58decode' }]);
  }

  const origLen = scrubbed.length;
  const stripped = lstripByte(scrubbed, ALPHABET_BYTES[0]);
  const newLen = stripped.length;

  let acc;
  try {
    acc = b58decodeInt(stripped);
  } catch (error) {
    throw error.withFrames([{ file: MODULE, line: 124, name: 'b58decode' }]);
  }

  return concatBytes(repeatByte(0x00, origLen - newLen), intToBytes(acc));
}

