// Port of /workspace/dataset/base58/test15.py
//
// Encodes two strings to Base58 and decodes two Base58 strings, printing each
// result the way Python prints a bytes object.

import { ArgumentParser, SystemExit } from './lib/argparse.mjs';
import { b58decode, b58encode } from './lib/base58.mjs';
import { encodeUtf8 } from './lib/codecs.mjs';
import { bytesRepr } from './lib/pybytesrepr.mjs';
import { renderTraceback } from './lib/pyerrors.mjs';

const SCRIPT_NAME = 'test15';

// Frames for the two module-level statements that can raise, so an unhandled
// error prints the same traceback the interpreter would.
const DECODE_FRAMES = {
  c: {
    file: `${SCRIPT_NAME}.py`,
    line: 13,
    name: '<module>',
    source: 'dec1 = base58.b58decode(args.c)  # 解码Base58字符串1',
    caret: `${' '.repeat(7)}${'^'.repeat(24)}`,
  },
  d: {
    file: `${SCRIPT_NAME}.py`,
    line: 14,
    name: '<module>',
    source: 'dec2 = base58.b58decode(args.d)  # 解码Base58字符串2',
    caret: `${' '.repeat(7)}${'^'.repeat(24)}`,
  },
};

function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  for (const flag of ['--a', '--b', '--c', '--d']) {
    parser.addArgument([flag], { required: true });
  }
  return parser;
}

/** `base58.b58decode(value)`, tagged with the statement that invoked it. */
function decodeAt(value, frame) {
  try {
    return b58decode(value);
  } catch (error) {
    if (error.frames === undefined) {
      throw error;
    }
    throw error.withFrames([frame]);
  }
}

function main(argv) {
  const parser = buildParser(SCRIPT_NAME.concat('.mjs'));
  const args = parser.parseArgs(argv);

  const enc1 = b58encode(encodeUtf8(args.a)); // 编码字符串1
  const enc2 = b58encode(encodeUtf8(args.b)); // 编码字符串2
  const dec1 = decodeAt(args.c, DECODE_FRAMES.c); // 解码Base58字符串1
  const dec2 = decodeAt(args.d, DECODE_FRAMES.d); // 解码Base58字符串2
  console.log(bytesRepr(enc1));
  console.log(bytesRepr(enc2));
  console.log(bytesRepr(dec1));
  console.log(bytesRepr(dec2));
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    process.exit(error.code);
  }
  if (error.frames !== undefined) {
    process.stderr.write(renderTraceback(error));
    process.stderr.write(
      `[PYI-${process.pid}:ERROR] Failed to execute script '${SCRIPT_NAME}' `
        + 'due to unhandled exception!\n',
    );
    process.exit(1);
  }
  throw error;
}

