// Python's `linecache`, narrowed to what a traceback needs: fetch one line of a
// source file by number, returning '' when the file cannot be read.
//
// The lookup is relative to the process working directory, which is why the
// interpreter only echoes source into a traceback when the script file happens
// to sit in cwd.

import { readFileSync } from 'node:fs';

const cache = new Map();

function readLines(filename) {
  if (cache.has(filename)) {
    return cache.get(filename);
  }
  let lines;
  try {
    const text = readFileSync(filename, 'utf8');
    // Keep the line terminators: traceback offsets are measured against the
    // raw line, newline included.
    lines = text.match(/[^\n]*\n|[^\n]+/g) ?? [];
  } catch {
    lines = [];
  }
  cache.set(filename, lines);
  return lines;
}

/** `linecache.getline(filename, lineno)` — 1-indexed, '' when unavailable. */
export function getLine(filename, lineno) {
  const lines = readLines(filename);
  if (lineno < 1 || lineno > lines.length) {
    return '';
  }
  return lines[lineno - 1];
}

