// Traceback rendering, matching CPython 3.12's `StackSummary.format_frame_summary`
// including the `^^^` anchor row it draws under the failing expression.

import { getLine } from './linecache.mjs';
import { byteOffsetToCharOffset } from './codecs.mjs';
import { pyStrip, toCodePoints } from './pyunicode.mjs';

/**
 * Build the source echo and anchor rows for one frame.  Returns an empty list
 * when linecache has no source for it — which is the usual case, since the
 * lookup is relative to cwd.
 */
function formatFrameSource(frame) {
  const rawLine = getLine(frame.file, frame.line);
  const strippedLine = pyStrip(rawLine);
  if (strippedLine.length === 0) {
    return [];
  }

  const rows = [`    ${strippedLine}`];
  if (frame.colno === undefined || frame.endColno === undefined) {
    return rows;
  }

  const strippedCharacters = toCodePoints(rawLine).length - strippedLine.length;
  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno) + 1;
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno) + 1;

  // Anchors are only drawn when the expression covers less than the whole line.
  if (endOffset - startOffset < strippedLine.length) {
    const pad = Math.max(startOffset - strippedCharacters, 0);
    const carets = Math.max(endOffset - startOffset, 0);
    rows.push(`    ${' '.repeat(pad)}${'^'.repeat(carets)}`);
  }
  return rows;
}

export function renderTraceback(exception) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of exception.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    lines.push(...formatFrameSource(frame));
  }
  lines.push(`${exception.typeName}: ${exception.detail}`);
  return `${lines.join('\n')}\n`;
}

