// Text codecs, hand-rolled so the port stays free of typed-array helpers.

import { PyUnicodeEncodeError } from './pyerrors.mjs';
import { codecCharEscape, toCodePoints } from './pyunicode.mjs';

/**
 * Python's `str.encode()` (UTF-8, the default).  Lone surrogates cannot survive
 * the runtime's own argv decoding, so any that appear are already the
 * replacement character's stand-in and are encoded as U+FFFD.
 */
export function encodeUtf8(text) {
  const out = [];
  for (const char of text) {
    let cp = char.codePointAt(0);
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/**
 * Python's `str.encode('ascii')` with the strict error handler.  The failure
 * message groups a run of consecutive non-ASCII characters, exactly as the
 * ASCII codec does.
 */
export function encodeAsciiStrict(text) {
  const chars = toCodePoints(text);
  const out = [];
  for (let i = 0; i < chars.length; i += 1) {
    const cp = chars[i].codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
      continue;
    }
    let end = i + 1;
    while (end < chars.length && chars[end].codePointAt(0) >= 0x80) {
      end += 1;
    }
    const where = end - i === 1
      ? `character '${codecCharEscape(cp)}' in position ${i}`
      : `characters in position ${i}-${end - 1}`;
    throw new PyUnicodeEncodeError(
      `'ascii' codec can't encode ${where}: ordinal not in range(128)`,
    );
  }
  return out;
}

