// A faithful subset of Python's `argparse`, covering the store/help actions and
// the exact usage, help and error wording the reference build emits.

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor({ optionStrings, dest, required, help, nargs, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required ?? false;
    this.help = help;
    this.nargs = nargs ?? null;
    this.isHelp = isHelp ?? false;
    this.metavar = dest.toUpperCase();
  }

  /** `_get_action_name`: how the action is named in the "required" message. */
  get name() {
    return this.optionStrings[0];
  }

  /** `_format_action_invocation` for the options list. */
  formatInvocation() {
    if (this.nargs === 0) {
      return this.optionStrings.join(', ');
    }
    return this.optionStrings.map((opt) => `${opt} ${this.metavar}`).join(', ');
  }

  /** `_format_args` as it appears in the usage line. */
  formatUsage() {
    const body = this.nargs === 0
      ? this.optionStrings[0]
      : `${this.optionStrings[0]} ${this.metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

/** Raised instead of calling exit() directly, so the entry point owns process control. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.code = code;
  }
}

export class ArgumentParser {
  constructor({ prog, stdout, stderr } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.stdout = stdout ?? ((text) => process.stdout.write(text));
    this.stderr = stderr ?? ((text) => process.stderr.write(text));

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest = (options.dest ?? optionStrings[optionStrings.length - 1])
      .replace(/^--?/, '')
      .replace(/-/g, '_');
    const action = new Action({ optionStrings, dest, ...options });
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsage());
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    // argparse aligns help text at min(longest invocation + 2, 24) + 2.
    const invocations = this.actions.map((action) => action.formatInvocation());
    const longest = Math.max(...invocations.map((text) => text.length));
    const helpPosition = Math.min(longest + 2, 24) + 2;

    const lines = [this.formatUsage(), '\noptions:\n'];
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (action.help === undefined) {
        lines.push(`  ${invocation}\n`);
        return;
      }
      const pad = ' '.repeat(Math.max(helpPosition - invocation.length - 2, 1));
      lines.push(`  ${invocation}${pad}${action.help}\n`);
    });
    return lines.join('');
  }

  error(message) {
    this.stderr(this.formatUsage());
    this.stderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * `_parse_optional`.  Returns null when the token is a plain argument, or
   * `{ action, optionString, explicitArg }` where a null action means "looks
   * like an option but matches nothing we know".
   */
  parseOptional(argString) {
    if (argString.length === 0) {
      return null;
    }
    if (argString[0] !== '-') {
      return null;
    }
    if (this.optionStringActions.has(argString)) {
      return {
        action: this.optionStringActions.get(argString),
        optionString: argString,
        explicitArg: null,
      };
    }
    if (argString.length === 1) {
      return null;
    }
    if (argString.includes('=')) {
      const splitAt = argString.indexOf('=');
      const optionString = argString.slice(0, splitAt);
      const explicitArg = argString.slice(splitAt + 1);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          explicitArg,
        };
      }
    }

    const candidates = this.getOptionTuples(argString);
    if (candidates.length > 1) {
      const options = candidates.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (candidates.length === 1) {
      return candidates[0];
    }

    // No negative-number-like option strings are defined, so anything that
    // parses as a negative number is a value, not an option.
    if (NEGATIVE_NUMBER.test(argString)) {
      return null;
    }
    if (argString.includes(' ')) {
      return null;
    }
    return { action: null, optionString: argString, explicitArg: null };
  }

  /** `_get_option_tuples`: prefix matching for abbreviated options. */
  getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      let optionPrefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const splitAt = argString.indexOf('=');
        optionPrefix = argString.slice(0, splitAt);
        explicitArg = argString.slice(splitAt + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
      return result;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  parseArgs(argStrings) {
    const [namespace, extras] = this.parseKnownArgs(argStrings);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argStrings) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) {
        namespace[action.dest] = null;
      }
    }

    // Classify every token: 'O' option, 'A' argument, '-' the bare separator.
    // Everything after the first '--' is forced to 'A'.
    const pattern = [];
    const optionTuples = new Map();
    let afterSeparator = false;
    argStrings.forEach((argString, index) => {
      if (afterSeparator) {
        pattern.push('A');
        return;
      }
      if (argString === '--') {
        pattern.push('-');
        afterSeparator = true;
        return;
      }
      const tuple = this.parseOptional(argString);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(index, tuple);
        pattern.push('O');
      }
    });

    const seen = new Set();
    const extras = [];
    let index = 0;
    while (index < argStrings.length) {
      const tuple = optionTuples.get(index);
      if (tuple === undefined) {
        // No positional actions are defined, so nothing consumes this token.
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }
      index = this.consumeOptional(index, tuple, argStrings, pattern, namespace, seen);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  consumeOptional(startIndex, tuple, argStrings, pattern, namespace, seen) {
    const { action, optionString, explicitArg } = tuple;
    if (action === null) {
      // Unknown option: reported verbatim among the unrecognized arguments.
      return startIndex + 1;
    }

    if (action.nargs === 0) {
      if (explicitArg !== null) {
        this.error(`argument ${optionString}: ignored explicit argument '${explicitArg}'`);
      }
      this.takeAction(action, null, namespace, seen);
      return startIndex + 1;
    }

    if (explicitArg !== null) {
      this.takeAction(action, explicitArg, namespace, seen);
      return startIndex + 1;
    }

    // For an optional with nargs=None the '-*' parts of the nargs pattern are
    // stripped, so the very next token must be classified as an argument.
    if (pattern[startIndex + 1] !== 'A') {
      this.error(`argument ${optionString}: expected one argument`);
    }
    this.takeAction(action, argStrings[startIndex + 1], namespace, seen);
    return startIndex + 2;
  }

  takeAction(action, value, namespace, seen) {
    seen.add(action);
    if (action.isHelp) {
      this.stdout(this.formatHelp());
      throw new SystemExit(0);
    }
    namespace[action.dest] = value;
  }
}

