    file: `${SCRIPT_NAME}.py`,
    line: 13,
    name: '<module>',
    source: 'dec1 = base58.b58decode(args.c)  # 解码Base58字符串1',
    caret: `${' '.repeat(7)}${'^'.repeat(24)}`,
  },
  d: {
    file: `${SCRIPT_NAME}.py`,
    line: 14,
    name: '<module>',
    source: 'dec2 = base58.b58decode(args.d)  # 解码Base58字符串2',
    caret: `${' '.repeat(7)}${'^'.repeat(24)}`,
  },
};

function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  for (const flag of ['--a', '--b', '--c', '--d']) {
    parser.addArgument([flag], { required: true });
  }
  return parser;
}

