// Normalize the PyInstaller trailer (embeds the PID) and the prog name.
const normalize = (text) => text
  .replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]')
  .replace(/test15_executable|test15\.mjs/g, 'PROG');

let failures = 0;
for (const argv of CASES) {
  const ref = spawnSync(REF, argv, { encoding: 'utf8' });
  const port = spawnSync(process.execPath, [...PORT, ...argv], { encoding: 'utf8' });
  const diffs = [];
  if (ref.stdout !== port.stdout) diffs.push(`stdout\n  ref : ${JSON.stringify(ref.stdout)}\n  port: ${JSON.stringify(port.stdout)}`);
  if (ref.status !== port.status) diffs.push(`exit: ref=${ref.status} port=${port.status}`);
  if (normalize(ref.stderr) !== normalize(port.stderr)) {
    diffs.push(`stderr\n  ref : ${JSON.stringify(normalize(ref.stderr))}\n  port: ${JSON.stringify(normalize(port.stderr))}`);
  }
  if (diffs.length > 0) {
    failures += 1;
    console.log(`FAIL ${JSON.stringify(argv)}`);
    for (const diff of diffs) console.log(`  ${diff}`);
  }
}
console.log(`\n${CASES.length - failures}/${CASES.length} cases matched`);
process.exit(failures === 0 ? 0 : 1);

