#!/usr/bin/env node
// Differential harness: runs the reference executable and the port over the
// same argv and compares stdout / stderr-shape / exit code.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test15_executable';
const PORT = ['/output/test15.mjs'];

const CASES = [
  ['--a', 'TPcTsjvTNHtabUBA', '--b', 'U5Oa2ji3Q', '--c', '32eMed', '--d', '27sNiTaAuDXTYdy4WiQLdaWGA1Vt'],
