85	    '--b', pick(TEXT, Math.floor(rand() * 12)),
86	    '--c', pick(ALPHABET, Math.floor(rand() * 45)),
87	    '--d', pick(ALPHABET, Math.floor(rand() * 60)),
88	  ]);
89	}
90	
91	// Normalize the PyInstaller trailer (embeds the PID) and the prog name, which
92	// argparse derives from the program filename and so differs by construction.
93	const normalize = (text) => text
94	  .replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]')
95	  .replace(/test15_executable|test15\.mjs/g, 'PROG');
96	
97	let failures = 0;
98	for (const argv of CASES) {
99	  const ref = spawnSync(REF, argv, { encoding: 'utf8', cwd: CWD });
100	  const port = spawnSync(process.execPath, [...PORT, ...argv], { encoding: 'utf8', cwd: CWD });
101	  const diffs = [];
102	  if (normalize(ref.stdout) !== normalize(port.stdout)) diffs.push(`stdout\n  ref : ${JSON.stringify(ref.stdout)}\n  port: ${JSON.stringify(port.stdout)}`);
103	  if (ref.status !== port.status) diffs.push(`exit: ref=${ref.status} port=${port.status}`);
104	  if (normalize(ref.stderr) !== normalize(port.stderr)) {
105	    diffs.push(`stderr\n  ref : ${JSON.stringify(normalize(ref.stderr))}\n  port: ${JSON.stringify(normalize(port.stderr))}`);
106	  }
107	  if (diffs.length > 0) {
108	    failures += 1;
109	    console.log(`FAIL ${JSON.stringify(argv)}`);
110	    for (const diff of diffs) console.log(`  ${diff}`);
111	  }
112	}
113	console.log(`\n${CASES.length - failures}/${CASES.length} cases matched (cwd=${CWD})`);
114	process.exit(failures === 0 ? 0 : 1);
